window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-20bd7fe42917246a"]={"versions": [{"id": "FIG-20bd7fe42917246a", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Konzeptionelles Architektur- und Strukturübersichtsdiagramm zur Gliederung von Timing-Analyse-Aspekten im AUTOSAR-Kontext. Das Schaubild visualisiert die methodische Einordnung von Timing-Fragestellungen entlang von Abstraktionsebenen und Dokumentkapiteln: von der funktionalen Architektur über Einzel-Steuergeräte (ECU) und Netzwerk-Topologien bis hin zum verteilten Gesamtsystem.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich in vier Hauptblöcke:</p>\n<ul class=\"fig-list\">\n<li><strong>Functional architecture (Ch. 2)</strong>: Enthält ein Funktionsnetzwerk mit Sensorblock $s_1$, Funktionsblöcken $f_1$ (mit internen Zuständen/Parametern), $f_2$, einer Rückkopplung über Funktionsblock $f_3$ sowie einem Aktorblock $a_1$. Ein Begleittext benennt als Thema „Timing requirements“.</li>\n<li><strong>ECU (Ch. 3)</strong>: Zeigt einen Software-Architektur-Stack mit Software Components (SWC), dem Runtime Environment (RTE) und der Basissoftware (BSW). Themen umfassen u. a. CPU-Load (Average und Peak), Execution times (Worst-, typical-case), Integration of SWCs, Interrupt loads und dynamisches Verhalten bzw. Jitter.</li>\n<li><strong>Network (Ch. 4)</strong>: Zeigt eine hierarchische/verzweigte Netzwerkarchitektur aus verbundenen Bus-Knoten. Themen umfassen Network load, Response times, Message displacement/drops sowie Dynamic behavior/Jitter.</li>\n<li><strong>Distributed System (Ch. 5)</strong>: Zeigt zwei Standard-ECUs und eine Gateway-ECU (jeweils mit SWC, RTE, BSW) verbunden über Busse, ein End-to-End-Timing-Segmentdiagramm sowie Themen wie Buffer sizes, End-to-end timing chains, Routing between networks, Sampling effects und Dynamic behavior/Jitter.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm stellt keinen sequenziellen Laufzeit- oder Protokollablauf dar, sondern bildet den methodischen Fluss der Timing-Analyse ab: Ausgehend von funktionalen Anforderungen im Funktionsnetzwerk erfolgt die Verfeinerung und Analyse auf Steuergeräteebene (Task-Ausführung, RTE-Kommunikation, BSW), auf Netzwerkebene (Busübertragung, Arbitrierung, Latenzen) sowie übergreifend im Gesamtsystem (End-to-End-Wirkketten über Gateways hinweg).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Schaubild dient als methodischer Leitfaden und Gliederungsübersicht für die Timing-Spezifikation (AUTOSAR TR TimingAnalysis). Es ordnet die normativen Timing-Konzepte (wie End-to-End Latency, Execution Time Constraints, Network Latencies) den jeweiligen Architektur-Ebenen und Kapiteln zu. Entwickler und Systemarchitekten leiten daraus ab, auf welchen Abstraktions- und Integrationsebenen spezifische Timing-Eigenschaften zu modellieren, analysieren und verifizieren sind.</p>"}, {"id": "FIG-80a6ecca4f759811", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Konzeptionelles Architektur- und Strukturübersichtsdiagramm zur Gliederung von Timing-Analyse-Aspekten im AUTOSAR-Kontext. Das Schaubild visualisiert die methodische Einordnung von Timing-Fragestellungen entlang von Abstraktionsebenen und Dokumentkapiteln: von der funktionalen Architektur über Einzel-Steuergeräte (ECU) und Netzwerk-Topologien bis hin zum verteilten Gesamtsystem.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich in vier Hauptblöcke:</p>\n<ul class=\"fig-list\">\n<li><strong>Functional architecture (Ch. 2)</strong>: Enthält ein Funktionsnetzwerk mit Sensorblock $s_1$, Funktionsblöcken $f_1$ (mit internen Zuständen/Parametern), $f_2$, einer Rückkopplung über Funktionsblock $f_3$ sowie einem Aktorblock $a_1$. Ein Begleittext benennt als Thema „Timing requirements“.</li>\n<li><strong>ECU (Ch. 3)</strong>: Zeigt einen Software-Architektur-Stack mit Software Components (SWC), dem Runtime Environment (RTE) und der Basissoftware (BSW). Themen umfassen u. a. CPU-Load (Average und Peak), Execution times (Worst-, typical-case), Integration of SWCs, Interrupt loads und dynamisches Verhalten bzw. Jitter.</li>\n<li><strong>Network (Ch. 4)</strong>: Zeigt eine hierarchische/verzweigte Netzwerkarchitektur aus verbundenen Bus-Knoten. Themen umfassen Network load, Response times, Message displacement/drops sowie Dynamic behavior/Jitter.</li>\n<li><strong>Distributed System (Ch. 5)</strong>: Zeigt zwei Standard-ECUs und eine Gateway-ECU (jeweils mit SWC, RTE, BSW) verbunden über Busse, ein End-to-End-Timing-Segmentdiagramm sowie Themen wie Buffer sizes, End-to-end timing chains, Routing between networks, Sampling effects und Dynamic behavior/Jitter.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm stellt keinen sequenziellen Laufzeit- oder Protokollablauf dar, sondern bildet den methodischen Fluss der Timing-Analyse ab: Ausgehend von funktionalen Anforderungen im Funktionsnetzwerk erfolgt die Verfeinerung und Analyse auf Steuergeräteebene (Task-Ausführung, RTE-Kommunikation, BSW), auf Netzwerkebene (Busübertragung, Arbitrierung, Latenzen) sowie übergreifend im Gesamtsystem (End-to-End-Wirkketten über Gateways hinweg).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Schaubild dient als methodischer Leitfaden und Gliederungsübersicht für die Timing-Spezifikation (AUTOSAR TR TimingAnalysis). Es ordnet die normativen Timing-Konzepte (wie End-to-End Latency, Execution Time Constraints, Network Latencies) den jeweiligen Architektur-Ebenen und Kapiteln zu. Entwickler und Systemarchitekten leiten daraus ab, auf welchen Abstraktions- und Integrationsebenen spezifische Timing-Eigenschaften zu modellieren, analysieren und verifizieren sind.</p>"}, {"id": "FIG-6fed23fe09b1596a", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Konzeptionelles Übersichtsdiagramm zur Strukturierung von Use Cases der Timing-Analyse im AUTOSAR-Kontext. Das Schaubild ordnet konkrete methodische Anwendungsfälle den Architekturebenen und entsprechenden Kapiteln zu: Function Architecture, Implementation of Distributed Functions, ECU Implementation und Network Implementation.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm besteht aus vier separaten Boxen mit blau hinterlegten Titelzeilen:</p>\n<ul class=\"fig-list\">\n<li><strong>Function Architecture (Chapter 2)</strong>: Beinhaltet das Blockdiagramm der Funktionsarchitektur ($s_1$, $f_1$, $f_2$, $f_3$, $a_1$) und die Beispiel-Anwendungsfälle „Identify timing requirements“ sowie „Map events to implementation“.</li>\n<li><strong>Implementation of Distributed Functions (Chapter 5)</strong>: Beinhaltet die Architekturskizze verteilter Steuergeräte (zwei ECUs und eine Gateway-ECU) mit End-to-End-Timing-Leiste sowie die Use Cases „Derive per hop timing requirements“ und „Specify Timing Requirements for Signals/Parameters“.</li>\n<li><strong>ECU Implementation (Chapter 3)</strong>: Beinhaltet das Software-Architektur-Schichtenmodell (SWC, RTE, BSW) mit den Use Cases „Validate Timing after SWC integration“ und „Optimize Timing of an ECU“.</li>\n<li><strong>Network Implementation (Chapter 4)</strong>: Beinhaltet die Netzwerk-Topologieskizze mit den Use Cases „Derive network timing“ und „Remapping of an existing communication link“.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Kein dynamischer Protokoll- oder Laufzeitablauf. Dargestellt ist die Zuordnung typischer Entwurfs- und Verifikationsaktivitäten zu den Phasen des AUTOSAR-Entwicklungsprozesses: Spezifikation funktionaler Timing-Vorgaben, Dekomposition auf verteilte Teilsysteme, gefolgt von der isolierten Timing-Validierung und -Optimierung auf ECU- und Netzwerkebene.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Schaubild dient als methodischer Leitfaden und Gliederungsübersicht für die Timing-Spezifikation (AUTOSAR TR TimingAnalysis). Es ordnet die normativen Timing-Konzepte (wie End-to-End Latency, Execution Time Constraints, Network Latencies) den jeweiligen Architektur-Ebenen und Kapiteln zu. Entwickler und Systemarchitekten leiten daraus ab, auf welchen Abstraktions- und Integrationsebenen spezifische Timing-Eigenschaften zu modellieren, analysieren und verifizieren sind.</p>"}, {"id": "FIG-f564f157de71ff2e", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Konzeptionelles Übersichtsdiagramm zur Strukturierung von Use Cases der Timing-Analyse im AUTOSAR-Kontext. Das Schaubild ordnet konkrete methodische Anwendungsfälle den Architekturebenen und entsprechenden Kapiteln zu: Function Architecture, Implementation of Distributed Functions, ECU Implementation und Network Implementation.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich in vier Blöcke mit Titelbalken und zugeordneten Beispiel-Use-Cases:</p>\n<ul class=\"fig-list\">\n<li><strong>Function Architecture (Chapter 4)</strong>: Funktionsarchitektur-Blockdiagramm ($s_1$, $f_1$, $f_2$, $f_3$, $a_1$) mit den Use Cases „Identify timing requirements“ und „Map events to implementation“.</li>\n<li><strong>Implementation of Distributed Functions (Chapter 5)</strong>: Darstellung verteilter ECUs mit Gateway und End-to-End-Timing sowie den Use Cases „Derive per hop timing requirements“ und „Specify Timing Requirements for Signals/Parameters“.</li>\n<li><strong>ECU Implementation (Chapter 7)</strong>: Schichtenmodell (SWC, RTE, BSW) mit den Use Cases „Validate Timing after SWC integration“ und „Optimize Timing of an ECU“.</li>\n<li><strong>Network Implementation (Chapter 6)</strong>: Netzwerktopologie mit den Use Cases „Derive network timing“ und „Remapping of an existing communication link“.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Kein dynamischer Protokoll- oder Laufzeitablauf. Dargestellt ist die Zuordnung typischer Entwurfs- und Verifikationsaktivitäten zu den Phasen des AUTOSAR-Entwicklungsprozesses: Spezifikation funktionaler Timing-Vorgaben, Dekomposition auf verteilte Teilsysteme, gefolgt von der isolierten Timing-Validierung und -Optimierung auf ECU- und Netzwerkebene.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Schaubild dient als methodischer Leitfaden und Gliederungsübersicht für die Timing-Spezifikation (AUTOSAR TR TimingAnalysis). Es ordnet die normativen Timing-Konzepte (wie End-to-End Latency, Execution Time Constraints, Network Latencies) den jeweiligen Architektur-Ebenen und Kapiteln zu. Entwickler und Systemarchitekten leiten daraus ab, auf welchen Abstraktions- und Integrationsebenen spezifische Timing-Eigenschaften zu modellieren, analysieren und verifizieren sind.</p>"}, {"id": "FIG-71c6f02357769a23", "releases": ["R19-11", "R20-11", "R21-11", "R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Konzeptionelles Übersichtsdiagramm zur Strukturierung von Use Cases der Timing-Analyse im AUTOSAR-Kontext. Das Schaubild ordnet konkrete methodische Anwendungsfälle den Architekturebenen und entsprechenden Kapiteln zu: Function Architecture, Implementation of Distributed Functions, ECU Implementation und Network Implementation.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich in vier Blöcke mit Titelbalken und zugeordneten Beispiel-Use-Cases:</p>\n<ul class=\"fig-list\">\n<li><strong>Function Architecture (Chapter 2)</strong>: Funktionsarchitektur-Blockdiagramm ($s_1$, $f_1$, $f_2$, $f_3$, $a_1$) mit den Use Cases „Identify timing requirements“ und „Map events to implementation“.</li>\n<li><strong>Implementation of Distributed Functions (Chapter 5)</strong>: Darstellung verteilter ECUs mit Gateway und End-to-End-Timing sowie den Use Cases „Derive per hop timing requirements“ und „Specify Timing Requirements for functional interfaces based on Signals/Parameters“.</li>\n<li><strong>ECU Implementation (Chapter 3)</strong>: Schichtenmodell (SWC, RTE, BSW) mit den Use Cases „Validate Timing after SW-C integration“ und „Optimize Timing of an ECU“.</li>\n<li><strong>Network Implementation (Chapter 4)</strong>: Netzwerktopologie mit den Use Cases „Derive network timing“ und „Remapping of an existing communication link“.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Kein dynamischer Protokoll- oder Laufzeitablauf. Dargestellt ist die Zuordnung typischer Entwurfs- und Verifikationsaktivitäten zu den Phasen des AUTOSAR-Entwicklungsprozesses: Spezifikation funktionaler Timing-Vorgaben, Dekomposition auf verteilte Teilsysteme, gefolgt von der isolierten Timing-Validierung und -Optimierung auf ECU- und Netzwerkebene.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Schaubild dient als methodischer Leitfaden und Gliederungsübersicht für die Timing-Spezifikation (AUTOSAR TR TimingAnalysis). Es ordnet die normativen Timing-Konzepte (wie End-to-End Latency, Execution Time Constraints, Network Latencies) den jeweiligen Architektur-Ebenen und Kapiteln zu. Entwickler und Systemarchitekten leiten daraus ab, auf welchen Abstraktions- und Integrationsebenen spezifische Timing-Eigenschaften zu modellieren, analysieren und verifizieren sind.</p>"}], "trans": [{"from": "FIG-20bd7fe42917246a", "to": "FIG-80a6ecca4f759811", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-80a6ecca4f759811", "to": "FIG-6fed23fe09b1596a", "fr": "R4.2.2", "tr": "R4.3.1", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Layout und Strukturierung umgestellt: Die vier Aspekte sind nicht mehr als ein oberer Querblock („Functional architecture“) und drei nebeneinanderliegende Spalten („ECU“, „Network“, „Distributed System“) angeordnet, sondern als vier separate Blöcke („Function Architecture“, „Implementation of Distributed Functions“, „ECU Implementation“, „Network Implementation“) mit abgerundeten Rahmen und blauen Titelbalken.</li>\n<li>Titelzeilen redaktionell überarbeitet:</li>\n<li>„Functional architecture (Ch. 2)“ zu „Function Architecture (Chapter 2)“</li>\n<li>„ECU (Ch. 3)“ zu „ECU Implementation (Chapter 3)“</li>\n<li>„Network (Ch. 4)“ zu „Network Implementation (Chapter 4)“</li>\n<li>„Distributed System (Ch. 5)“ zu „Implementation of Distributed Functions (Chapter 5)“</li>\n<li>Unterabschnitte „Topics“ mit Stichpunktlisten (u. a. CPU-Load, Execution times, Network load, Buffer sizes) durch „Example Use Cases:“ mit spezifischen Anwendungsfällen je Bereich ersetzt.</li>\n</ul>"}, {"from": "FIG-6fed23fe09b1596a", "to": "FIG-f564f157de71ff2e", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Kapitelnummern in drei Titelbalken angepasst:</li>\n<li>„Function Architecture (Chapter 2)“ zu „Function Architecture (Chapter 4)“</li>\n<li>„Network Implementation (Chapter 4)“ zu „Network Implementation (Chapter 6)“</li>\n<li>„ECU Implementation (Chapter 3)“ zu „ECU Implementation (Chapter 7)“</li>\n<li>Titelbalken „Implementation of Distributed Functions (Chapter 5)“ bleibt unverändert.</li>\n</ul>"}, {"from": "FIG-f564f157de71ff2e", "to": "FIG-71c6f02357769a23", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Kapitelnummern in drei Titelbalken zurückgesetzt:</li>\n<li>„Function Architecture (Chapter 4)“ zu „Function Architecture (Chapter 2)“</li>\n<li>„ECU Implementation (Chapter 7)“ zu „ECU Implementation (Chapter 3)“</li>\n<li>„Network Implementation (Chapter 6)“ zu „Network Implementation (Chapter 4)“</li>\n<li>Unter „Implementation of Distributed Functions (Chapter 5)“ Use Case präzisiert: „Specify Timing Requirements for Signals/Parameters“ zu „Specify Timing Requirements for functional interfaces based on Signals/Parameters“.</li>\n<li>Unter „ECU Implementation (Chapter 3)“ Schreibweise angepasst: „Validate Timing after SWC integration“ zu „Validate Timing after SW-C integration“.</li>\n</ul>"}]};
